<script setup lang="ts">
import {ref} from 'vue'
import ImageUpload from '../components/ImageUpload.vue'
import CompareImages from '../components/CompareImages.vue'
import MethodSelect from '../components/MethodSelect.vue'
import {post,imageForm,useTask,number} from '../api/client'
const file=ref<File>(),method=ref('adaptive'),result=ref<any>(null)
const {busy,run}=useTask()
function execute(){if(file.value)run(async()=>{result.value=await post('/face/detect',imageForm(file.value!,{method:method.value}))})}
</script>
<template><div class="workbench"><section class="card controls"><div class="section-heading"><h2>检测设置</h2><span class="step-label">01</span></div><ImageUpload @change="files=>{file=files[0];result=null}"/><el-form label-position="top"><el-form-item label="对照组增强方法"><MethodSelect v-model="method"/></el-form-item></el-form><el-button type="primary" class="full-width" :disabled="!file" :loading="busy" @click="execute">运行双路检测</el-button><div class="note">支持单图多人脸。绿色框为检测位置，彩色点为五点关键点。两路使用同一模型与检测阈值。</div></section><section class="card result-panel" v-loading="busy"><div class="section-heading"><h2>检测结果对比</h2><span class="pill">InsightFace / SCRFD</span></div><CompareImages :original="result?.original.image" :enhanced="result?.enhanced.image" left-label="原始图像检测" right-label="增强图像检测"/><div v-if="result" class="detection-metrics"><div v-for="key in ['original','enhanced']" :key="key"><span>{{key==='original'?'原始图像':'增强图像'}}</span><strong>{{result[key].count}}<small> 张人脸</small></strong><p>模型推理 {{number(result[key].elapsed_ms)}} ms</p><p v-if="key==='enhanced'">含增强总耗时 {{number(result.enhanced.total_ms)}} ms</p></div></div><div v-if="result" class="steps"><el-tag v-for="s in result.steps" :key="s">{{s}}</el-tag></div></section></div><section v-if="result" class="card quality-card"><div class="section-heading"><h2>人脸明细与对齐裁剪</h2><span>五点对齐 · 112 × 112</span></div><el-tabs><el-tab-pane v-for="key in ['original','enhanced']" :key="key" :label="key==='original'?'原始检测':'增强检测'"><el-table :data="result[key].faces" empty-text="未检测到人脸"><el-table-column label="对齐人脸" width="130"><template #default="{row}"><img :src="row.aligned_crop" class="face-thumb" alt="对齐人脸裁剪"></template></el-table-column><el-table-column label="检测置信度"><template #default="{row}">{{number(row.confidence,4)}}</template></el-table-column><el-table-column label="边界框 [x1,y1,x2,y2]"><template #default="{row}">{{row.bbox.map((n:number)=>Math.round(n)).join(', ')}}</template></el-table-column><el-table-column label="关键点数"><template #default="{row}">{{row.keypoints.length}}</template></el-table-column></el-table></el-tab-pane></el-tabs></section></template>
